example_usage:
// Example: long-lived chat session
ctx := context.Background()
sh := client.NewStreamHandle()
// start with a small per-RPC deadline to bound network calls
if err := sh.Start(context.WithTimeout(ctx, 5*time.Second), StartOptions{HeartbeatInterval: 30*time.Second}); err != nil {
  log.Fatalf("start failed: %v", err)
}
// sending a message with a short deadline for the send RPC
sendCtx, cancel := context.WithTimeout(ctx, 2*time.Second)
defer cancel()
if err := sh.Send(sendCtx, &Message{Text: "hello"}); err != nil {
  if errors.Is(err, ErrResumeFailed) {
    // try resume logic or surface to caller
  }
}
// receiving with bounded deadline
recvCtx, cancelr := context.WithTimeout(ctx, 6*time.Second)
defer cancelr()
msg, err := sh.Recv(recvCtx)
if err != nil {
  // handle ErrDeadlineExceeded vs ErrStreamClosed differently
}
